.lx-loader {
    animation: 1.8s ease-in-out -.16s infinite both lx-loader-load7;
    border-radius: 50%;
    color: #232635;
    font-size: 10px;
    height: 2.5em;
    margin: 80px auto;
    position: relative;
    text-indent: -9999em;
    transform: translateZ(0);
    width: 2.5em
}

.lx-loader.ng-hide.ng-hide-animate {
    display: none !important
}

.lx-loader::after,
.lx-loader::before {
    animation: 1.8s ease-in-out infinite both lx-loader-load7;
    border-radius: 50%;
    height: 2.5em;
    width: 2.5em
}

.lx-loader::before {
    animation-delay: -.32s;
    content: "";
    left: -3.5em;
    position: absolute;
    top: 0
}

.lx-loader::after {
    content: "";
    left: 3.5em;
    position: absolute;
    top: 0
}

@keyframes lx-loader-load7 {
    0%,
    100%,
    80% {
        box-shadow: 0 2.5em 0 -1.3em
    }
    40% {
        box-shadow: 0 2.5em 0 0
    }
}

.lx-small-loader__container {
    height: 45px;
    width: 45px;
    margin: 0 auto;
    overflow: visible;
    transform: scale(.65)
}

.lx-small-loader__circle {
    position: absolute;
    display: block;
    transform-origin: 22.5px 22.5px;
    fill: #232635;
    color: #232635;
    font-family: Verdana;
    font-style: normal;
    font-size: 1.15em;
    animation: 1.2s linear infinite lx-small-loader-opacity;
    fill-opacity: 0
}

.lx-small-loader__circle:nth-child(12n+1) {
    animation-delay: -.1s;
    transform: rotate(-30deg) translate(5px, 5px)
}

.lx-small-loader__circle:nth-child(12n+2) {
    animation-delay: -.2s;
    transform: rotate(-60deg) translate(5px, 5px)
}

.lx-small-loader__circle:nth-child(12n+3) {
    animation-delay: -.3s;
    transform: rotate(-90deg) translate(5px, 5px)
}

.lx-small-loader__circle:nth-child(12n+4) {
    animation-delay: -.4s;
    transform: rotate(-120deg) translate(5px, 5px)
}

.lx-small-loader__circle:nth-child(12n+5) {
    animation-delay: -.5s;
    transform: rotate(-150deg) translate(5px, 5px)
}

.lx-small-loader__circle:nth-child(12n+6) {
    animation-delay: -.6s;
    transform: rotate(-180deg) translate(5px, 5px)
}

.lx-small-loader__circle:nth-child(12n+7) {
    animation-delay: -.7s;
    transform: rotate(-210deg) translate(5px, 5px)
}

.lx-small-loader__circle:nth-child(12n+8) {
    animation-delay: -.8s;
    transform: rotate(-240deg) translate(5px, 5px)
}

.lx-small-loader__circle:nth-child(12n+9) {
    animation-delay: -.9s;
    transform: rotate(-270deg) translate(5px, 5px)
}

.lx-small-loader__circle:nth-child(12n+10) {
    animation-delay: -1s;
    transform: rotate(-300deg) translate(5px, 5px)
